SELECT     imc.ITEM AS \"Case GTIN\",     imc.ITEM_DESC AS \"Case GTIN Description\",     im1.ITEM AS \"Consumer GTIN\",     im1.ITEM_DESC AS \"Consumer GTIN Description\",     pki.PACK_NO AS \"RMS Pack Number\",     im_pack.ITEM_DESC AS \"RMS Pack Description\",     NULL AS \"Shipper Indicator\",     SUM(pki.PACK_QTY) OVER (PARTITION BY pki.PACK_NO) AS \"Total Component Quantity for Pack\",     im.ITEM AS \"RMS Component Item\",     im.ITEM_DESC AS \"RMS Component Item Description\",     pki.PACK_QTY AS \"Component Quantity\" FROM rds_wv_packitem pki INNER JOIN rds_wv_item_master im ON im.ITEM = pki.ITEM INNER JOIN rds_wv_item_master im_pack ON im_pack.ITEM = pki.PACK_NO INNER JOIN rds_wv_item_master im1 ON im1.ITEM_PARENT = im.ITEM AND im1.PRIMARY_REF_ITEM_IND = 'Y' INNER JOIN rds_wv_item_master imc ON imc.ITEM_PARENT = pki.PACK_NO AND imc.PRIMARY_REF_ITEM_IND = 'Y'</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Case GTIN</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Case GTIN Description</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Consumer GTIN</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Consumer GTIN Description</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>RMS Pack Number</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>RMS Pack Description</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Shipper Indicator</ds:name><ds:datatype>varchar(0)</ds:datatype></ds:column><ds:column><ds:name>Total Component Quantity for Pack</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>RMS Component Item</